-- Demo data for the Project Estimator, DEMO tenants only (is_demo = true).
-- Run AFTER supabase/migrations/0131_estimator.sql. Idempotent.
-- Run scripts/seed-estimator-products-demo.sql AFTER this one (and AFTER
-- supabase/migrations/0133_item_types_and_bom.sql): the template below prices from
-- the catalogue's products and BOM kits, and that script creates them. Until it has
-- run the sample estimate's lines show "Needs a product".
-- GENERATED by scripts/gen-estimator-demo-seed.ts from the real engine; do not
-- edit by hand, change src/lib/estimator/demoProducts.ts or the engine and regenerate.
--
-- What it does, per demo tenant:
--   1. turns the estimator module on (tenants.features.estimator = true);
--   2. adds the template "Precast villa (illustrative)" if the tenant has none by that name, or, if it
--      already has it, REFRESHES its inputs, rates and rules to the current demo
--      template (E4 added the risk ranges and capacity rates; E5 renamed the groups and
--      options to plain words; the products-and-kits change replaced the blank rate
--      lines with catalogue products and BOM kits, named by SKU; the template's
--      version number is untouched);
--   3. adds ONE sample estimate "Sample villa, Riyadh (illustrative)" if it is not there yet, with
--      its computed lines, totals and 3D piece model already stored, so the
--      page shows everything without pressing Calculate. Margin 18%, VAT 15%.
--      If that sample estimate IS there and has no quote, it is REFRESHED the same
--      way: its figures, model and lines are replaced by the current demo template's
--      (the template now prices from the catalogue). Only that one demo estimate and only its own
--      lines; a sample that already has a quote is left alone; nothing else is
--      deleted.
-- Everything is illustrative: placeholder costs and rules, not a real price.

do $seed$
declare
  t uuid;
  tpl uuid;
  tpl_version int;
  acct uuid;
  cur text;
  est uuid;
  next_seq int;
  fresh boolean;
begin
  for t in select id from tenants where is_demo = true loop
    fresh := false;
    update tenants set features = coalesce(features, '{}'::jsonb) || '{"estimator": true}'::jsonb where id = t;

    if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Precast villa (illustrative)')) then
      insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules)
      values (
        t, 'Precast villa (illustrative)', 'ILLUSTRATIVE precast villa priced from the product catalogue: wall panels, the frame and the boundary wall come from BOM kits, slabs, stairs and parapets from products, transport and erection from services. All costs are placeholders to demonstrate the estimator, not any company''s real prices or method. Duplicate it and point the rules at your own products.', 'precast', 'precast_villa', 1, true, 'group',
        $inputs$[{"key":"floors","label":"Number of floors","type":"number","default":2,"min":1,"max":4,"unit":"floors","section":"Building"},{"key":"built_up_area_m2","label":"Built-up area per floor","type":"number","default":150,"min":20,"max":2000,"unit":"m²","help":"Area of ONE floor; every floor is the same shape.","section":"Building"},{"key":"wall_perimeter_m","label":"External wall perimeter (one floor)","type":"number","default":50,"min":10,"max":500,"unit":"m","help":"With the area, this fixes the length and depth of the building.","section":"Building"},{"key":"wall_height_m","label":"Floor-to-floor wall height","type":"number","default":3,"min":2.4,"max":6,"unit":"m","section":"Building"},{"key":"ext_wall_thickness_m","label":"External wall thickness","type":"number","default":0.2,"min":0.1,"max":0.5,"unit":"m","section":"Building"},{"key":"finish_level","label":"External finish","type":"select","default":"standard","options":[{"key":"basic","label":"Basic","value":1},{"key":"standard","label":"Standard","value":1.08},{"key":"premium","label":"Premium","value":1.18}],"quote_alternatives":true,"help":"Standard adds 8% and Premium 18% to the concrete price of the faces that show.","section":"Building"},{"key":"include_stairs","label":"Include precast stairs","type":"boolean","default":true,"section":"Stairs"},{"key":"stair_flights","label":"Stair flights","type":"number","default":2,"min":0,"max":10,"unit":"flights","section":"Stairs"},{"key":"boundary_wall_length_m","label":"Boundary wall length","type":"number","default":60,"min":0,"max":2000,"unit":"m","section":"Boundary wall"},{"key":"boundary_wall_height_m","label":"Boundary wall height","type":"number","default":2.4,"min":1,"max":4,"unit":"m","section":"Boundary wall"}]$inputs$::jsonb,
        $rates$[{"key":"concrete_density_t_m3","label":"Concrete density","unit":"t/m³","value":2.4},{"key":"wastage_pct","label":"Wastage on concrete, steel and boards","unit":"%","value":0},{"key":"concrete_cost_m3","label":"Precast concrete, supplied and cast","unit":"per m³","value":330,"low":297,"high":412.5},{"key":"mould_cost_m3","label":"Mould usage","unit":"per m³","value":90},{"key":"transport_load_capacity_t","label":"Transport capacity per load","unit":"t/load","value":25},{"key":"overhead_factor","label":"Factory and yard overhead (share of production cost)","unit":"fraction","value":0.12},{"key":"cap_cast_m3_per_day","label":"Casting capacity","unit":"m³/day","value":18},{"key":"cap_trucks_loads_per_day","label":"Truck loads leaving the factory","unit":"loads/day","value":4},{"key":"cap_crane_m3_per_day","label":"Crane erection capacity","unit":"m³/day","value":24},{"key":"transport_start_day","label":"Transport starts on day","unit":"day","value":5},{"key":"erection_start_day","label":"Erection starts on day","unit":"day","value":6},{"key":"iw_thickness_m","label":"Internal wall panel thickness","unit":"m","value":0.15},{"key":"slab_equiv_thickness_m","label":"Hollow-core slab: concrete per m² of slab","unit":"m","value":0.124},{"key":"bw_thickness_m","label":"Boundary wall panel thickness","unit":"m","value":0.1},{"key":"panel_pitch_m","label":"Parapet panel pitch","unit":"m","value":2.4}]$rates$::jsonb,
        $rules$[{"code":"iw","group":"Structure (floors, beams, inner walls)","description":"Internal wall panels","uom":"m2","qty":"vol_IW / iw_thickness_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"PC-WALL-SOLID"}},{"code":"sl","group":"Structure (floors, beams, inner walls)","description":"Hollow-core floor and roof slabs","uom":"m2","qty":"vol_SL / slab_equiv_thickness_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"PC-HCS-200"},"element_type":"slab"},{"code":"fr","group":"Structure (floors, beams, inner walls)","description":"Beams and columns","uom":"m3","qty":"vol_FR","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"KIT-FRAME-M3"},"element_type":"beam"},{"code":"ew","group":"External walls and parapet","description":"External wall panels (insulated)","uom":"m2","qty":"area_EW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"KIT-WALL-M2"},"element_type":"wall_panel"},{"code":"pr","group":"External walls and parapet","description":"Parapet panels","uom":"lm","qty":"n_PR * panel_pitch_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"PC-PARAPET"},"element_type":"parapet_panel"},{"code":"fin","group":"External walls and parapet","description":"External finish premium (extra concrete cost on the faces that show)","uom":"m3","qty":"(vol_EW + vol_PR + vol_BW) * (finish_level - 1)","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"}},{"code":"st","group":"Stairs","description":"Stair flights","uom":"nr","qty":"n_ST","component":"materials","cost":{"kind":"product","sku":"PC-STAIR"},"element_type":"stair"},{"code":"bw","group":"Boundary wall","description":"Boundary wall panels","uom":"m2","qty":"vol_BW / bw_thickness_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"KIT-BOUNDARY-M2"},"element_type":"boundary_panel"},{"code":"mld","group":"Production","description":"Mould usage","uom":"m3","qty":"vol_total","component":"moulds","cost":{"kind":"rate","rate":"mould_cost_m3"}},{"code":"plt","group":"Joints and fixings","description":"Steel connection plates (one per piece)","uom":"nr","qty":"n_total","component":"materials","cost":{"kind":"product","sku":"BO-PLATE"}},{"code":"grt","group":"Joints and fixings","description":"Grout for joints","uom":"bag","qty":"ceil(n_total / 4)","component":"materials","cost":{"kind":"product","sku":"CN-GROUT"}},{"code":"sea","group":"Joints and fixings","description":"Sealant to external wall joints","uom":"lm","qty":"n_EW * wall_height_m","component":"materials","cost":{"kind":"product","sku":"CN-SEALANT"}},{"code":"trl","group":"Delivery and erection","description":"Transport to site (loads by weight)","uom":"trip","qty":"ceil(weight_total / transport_load_capacity_t)","component":"transport","cost":{"kind":"product","sku":"SV-TRANSPORT"}},{"code":"ere","group":"Delivery and erection","description":"Crane and erection crew (days by crane capacity)","uom":"day","qty":"ceil(vol_total / cap_crane_m3_per_day)","component":"erection","cost":{"kind":"product","sku":"SV-ERECT"}},{"code":"ovh","group":"Overhead","description":"Factory and yard overhead","uom":"cost","qty":"sub_structure_floors_beams_inner_walls + sub_external_walls_and_parapet + sub_stairs + sub_boundary_wall + sub_production","component":"overhead","cost":{"kind":"rate","rate":"overhead_factor"}}]$rules$::jsonb
      );
    else
      -- Re-running REFRESHES an existing demo template to the current demo template
      -- (E4 added risk ranges, E5 plain group names). Only the
      -- template's inputs, rates and rules are replaced: the version, the sample
      -- estimate and every other tenant's data stay as they are. Nothing is deleted.
      update estimate_templates set
        inputs = $inputs$[{"key":"floors","label":"Number of floors","type":"number","default":2,"min":1,"max":4,"unit":"floors","section":"Building"},{"key":"built_up_area_m2","label":"Built-up area per floor","type":"number","default":150,"min":20,"max":2000,"unit":"m²","help":"Area of ONE floor; every floor is the same shape.","section":"Building"},{"key":"wall_perimeter_m","label":"External wall perimeter (one floor)","type":"number","default":50,"min":10,"max":500,"unit":"m","help":"With the area, this fixes the length and depth of the building.","section":"Building"},{"key":"wall_height_m","label":"Floor-to-floor wall height","type":"number","default":3,"min":2.4,"max":6,"unit":"m","section":"Building"},{"key":"ext_wall_thickness_m","label":"External wall thickness","type":"number","default":0.2,"min":0.1,"max":0.5,"unit":"m","section":"Building"},{"key":"finish_level","label":"External finish","type":"select","default":"standard","options":[{"key":"basic","label":"Basic","value":1},{"key":"standard","label":"Standard","value":1.08},{"key":"premium","label":"Premium","value":1.18}],"quote_alternatives":true,"help":"Standard adds 8% and Premium 18% to the concrete price of the faces that show.","section":"Building"},{"key":"include_stairs","label":"Include precast stairs","type":"boolean","default":true,"section":"Stairs"},{"key":"stair_flights","label":"Stair flights","type":"number","default":2,"min":0,"max":10,"unit":"flights","section":"Stairs"},{"key":"boundary_wall_length_m","label":"Boundary wall length","type":"number","default":60,"min":0,"max":2000,"unit":"m","section":"Boundary wall"},{"key":"boundary_wall_height_m","label":"Boundary wall height","type":"number","default":2.4,"min":1,"max":4,"unit":"m","section":"Boundary wall"}]$inputs$::jsonb,
        rates = $rates$[{"key":"concrete_density_t_m3","label":"Concrete density","unit":"t/m³","value":2.4},{"key":"wastage_pct","label":"Wastage on concrete, steel and boards","unit":"%","value":0},{"key":"concrete_cost_m3","label":"Precast concrete, supplied and cast","unit":"per m³","value":330,"low":297,"high":412.5},{"key":"mould_cost_m3","label":"Mould usage","unit":"per m³","value":90},{"key":"transport_load_capacity_t","label":"Transport capacity per load","unit":"t/load","value":25},{"key":"overhead_factor","label":"Factory and yard overhead (share of production cost)","unit":"fraction","value":0.12},{"key":"cap_cast_m3_per_day","label":"Casting capacity","unit":"m³/day","value":18},{"key":"cap_trucks_loads_per_day","label":"Truck loads leaving the factory","unit":"loads/day","value":4},{"key":"cap_crane_m3_per_day","label":"Crane erection capacity","unit":"m³/day","value":24},{"key":"transport_start_day","label":"Transport starts on day","unit":"day","value":5},{"key":"erection_start_day","label":"Erection starts on day","unit":"day","value":6},{"key":"iw_thickness_m","label":"Internal wall panel thickness","unit":"m","value":0.15},{"key":"slab_equiv_thickness_m","label":"Hollow-core slab: concrete per m² of slab","unit":"m","value":0.124},{"key":"bw_thickness_m","label":"Boundary wall panel thickness","unit":"m","value":0.1},{"key":"panel_pitch_m","label":"Parapet panel pitch","unit":"m","value":2.4}]$rates$::jsonb,
        rules = $rules$[{"code":"iw","group":"Structure (floors, beams, inner walls)","description":"Internal wall panels","uom":"m2","qty":"vol_IW / iw_thickness_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"PC-WALL-SOLID"}},{"code":"sl","group":"Structure (floors, beams, inner walls)","description":"Hollow-core floor and roof slabs","uom":"m2","qty":"vol_SL / slab_equiv_thickness_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"PC-HCS-200"},"element_type":"slab"},{"code":"fr","group":"Structure (floors, beams, inner walls)","description":"Beams and columns","uom":"m3","qty":"vol_FR","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"KIT-FRAME-M3"},"element_type":"beam"},{"code":"ew","group":"External walls and parapet","description":"External wall panels (insulated)","uom":"m2","qty":"area_EW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"KIT-WALL-M2"},"element_type":"wall_panel"},{"code":"pr","group":"External walls and parapet","description":"Parapet panels","uom":"lm","qty":"n_PR * panel_pitch_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"PC-PARAPET"},"element_type":"parapet_panel"},{"code":"fin","group":"External walls and parapet","description":"External finish premium (extra concrete cost on the faces that show)","uom":"m3","qty":"(vol_EW + vol_PR + vol_BW) * (finish_level - 1)","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"}},{"code":"st","group":"Stairs","description":"Stair flights","uom":"nr","qty":"n_ST","component":"materials","cost":{"kind":"product","sku":"PC-STAIR"},"element_type":"stair"},{"code":"bw","group":"Boundary wall","description":"Boundary wall panels","uom":"m2","qty":"vol_BW / bw_thickness_m","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"product","sku":"KIT-BOUNDARY-M2"},"element_type":"boundary_panel"},{"code":"mld","group":"Production","description":"Mould usage","uom":"m3","qty":"vol_total","component":"moulds","cost":{"kind":"rate","rate":"mould_cost_m3"}},{"code":"plt","group":"Joints and fixings","description":"Steel connection plates (one per piece)","uom":"nr","qty":"n_total","component":"materials","cost":{"kind":"product","sku":"BO-PLATE"}},{"code":"grt","group":"Joints and fixings","description":"Grout for joints","uom":"bag","qty":"ceil(n_total / 4)","component":"materials","cost":{"kind":"product","sku":"CN-GROUT"}},{"code":"sea","group":"Joints and fixings","description":"Sealant to external wall joints","uom":"lm","qty":"n_EW * wall_height_m","component":"materials","cost":{"kind":"product","sku":"CN-SEALANT"}},{"code":"trl","group":"Delivery and erection","description":"Transport to site (loads by weight)","uom":"trip","qty":"ceil(weight_total / transport_load_capacity_t)","component":"transport","cost":{"kind":"product","sku":"SV-TRANSPORT"}},{"code":"ere","group":"Delivery and erection","description":"Crane and erection crew (days by crane capacity)","uom":"day","qty":"ceil(vol_total / cap_crane_m3_per_day)","component":"erection","cost":{"kind":"product","sku":"SV-ERECT"}},{"code":"ovh","group":"Overhead","description":"Factory and yard overhead","uom":"cost","qty":"sub_structure_floors_beams_inner_walls + sub_external_walls_and_parapet + sub_stairs + sub_boundary_wall + sub_production","component":"overhead","cost":{"kind":"rate","rate":"overhead_factor"}}]$rules$::jsonb
      where tenant_id = t and lower(name) = lower('Precast villa (illustrative)');
    end if;

    select id, version into tpl, tpl_version from estimate_templates where tenant_id = t and lower(name) = lower('Precast villa (illustrative)');

    if tpl is not null then
      select id into est from estimates where tenant_id = t and name = 'Sample villa, Riyadh (illustrative)' order by created_at limit 1;

      if est is null then
        select id into acct from accounts where tenant_id = t order by name limit 1;
        select nullif(config->>'currency', '') into cur from tenants where id = t;

        select coalesce(max(nullif(regexp_replace(ref, '\D', '', 'g'), '')::int), 0) + 1 into next_seq
        from estimates where tenant_id = t and ref ~ '^EST-\d+$';

        insert into estimates (tenant_id, ref, name, account_id, template_id, template_version, status, params, currency, margin_pct, totals, model, notes)
        values (
          t, 'EST-' || lpad(next_seq::text, 4, '0'), 'Sample villa, Riyadh (illustrative)', acct, tpl, tpl_version, 'draft',
          $params${"floors":2,"built_up_area_m2":150,"wall_perimeter_m":50,"wall_height_m":3,"ext_wall_thickness_m":0.2,"finish_level":"standard","include_stairs":true,"stair_flights":2,"boundary_wall_length_m":60,"boundary_wall_height_m":2.4}$params$::jsonb, cur, 18,
          $totals${"cost_total":258672.36,"by_group":[{"key":"structure_floors_beams_inner_walls","name":"Structure (floors, beams, inner walls)","wbs_code":"1","line_count":3,"cost":75319.22},{"key":"external_walls_and_parapet","name":"External walls and parapet","wbs_code":"2","line_count":3,"cost":70779.95},{"key":"stairs","name":"Stairs","wbs_code":"3","line_count":1,"cost":12400},{"key":"boundary_wall","name":"Boundary wall","wbs_code":"4","line_count":1,"cost":9557.03},{"key":"production","name":"Production","wbs_code":"5","line_count":1,"cost":11780.73},{"key":"joints_and_fixings","name":"Joints and fixings","wbs_code":"6","line_count":3,"cost":14655},{"key":"delivery_and_erection","name":"Delivery and erection","wbs_code":"7","line_count":2,"cost":42600},{"key":"overhead","name":"Overhead","wbs_code":"8","line_count":1,"cost":21580.43}],"by_component":{"materials":182711.2,"moulds":11780.73,"labour":0,"overhead":21580.43,"transport":23400,"erection":19200,"other":0},"margin_pct":18,"margin_amount":46561.02,"price":305233.38,"vat_pct":15,"vat":45785.01,"price_incl_vat":351018.39,"unpriced":[],"unresolved":[],"pricing":{"iw":"product_cost","sl":"product_cost","fr":"kit_rollup","ew":"kit_rollup","pr":"product_cost","st":"product_cost","bw":"kit_rollup","plt":"product_cost","grt":"product_cost","sea":"product_cost","trl":"product_cost","ere":"product_cost"},"warnings":[]}$totals$::jsonb || jsonb_build_object('computed_at', now()),
